// Hand-written. Not generated by Speakeasy.
package provider

import (
	"io"
	"net/http"
	"strings"
	"testing"
)

func response(status int, body string) *http.Response {
	return &http.Response{
		Status:     http.StatusText(status),
		StatusCode: status,
		Proto:      "HTTP/1.1",
		ProtoMajor: 1,
		ProtoMinor: 1,
		Header:     http.Header{"Content-Type": []string{"application/json"}},
		Body:       io.NopCloser(strings.NewReader(body)),
	}
}

func TestServiceIsGone(t *testing.T) {
	// The exact body Authlete returns, for a deleted id and for one that never
	// existed. Both are identical.
	notFound := `{"resultCode":"A458203","resultMessage":"[A458203] (/service/get/) Service not found: entity is null."}`

	for _, tc := range []struct {
		name string
		res  *http.Response
		want bool
	}{
		{"service does not exist", response(http.StatusForbidden, notFound), true},
		{
			// A token that cannot see the service is a different thing. Removing
			// it from state would plan a second service next to the real one.
			name: "forbidden for another reason is not gone",
			res:  response(http.StatusForbidden, `{"resultCode":"A001202","resultMessage":"not authorized"}`),
			want: false,
		},
		{"a plain 404 is handled by the generated code", response(http.StatusNotFound, notFound), false},
		{"a success is not gone", response(http.StatusOK, `{"serviceName":"x"}`), false},
		{"a server error is not gone", response(http.StatusInternalServerError, "boom"), false},
		{"no response is not gone", nil, false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if got := serviceIsGone(tc.res); got != tc.want {
				t.Errorf("serviceIsGone() = %v, want %v", got, tc.want)
			}
		})
	}
}

// TestServiceIsGoneLeavesTheBodyReadable matters because the caller dumps the
// same response into a diagnostic afterwards. Draining it here would leave
// that diagnostic empty.
func TestServiceIsGoneLeavesTheBodyReadable(t *testing.T) {
	body := `{"resultCode":"A458203","resultMessage":"Service not found"}`
	res := response(http.StatusForbidden, body)

	if !serviceIsGone(res) {
		t.Fatal("expected the response to read as gone")
	}

	rest, err := io.ReadAll(res.Body)
	if err != nil {
		t.Fatalf("body is no longer readable: %v", err)
	}
	if string(rest) != body {
		t.Errorf("body is %q, want it unchanged as %q", rest, body)
	}
}

// TestServiceGoneMessage checks the diagnostic a data source raises. A data
// source cannot drop itself from state, so the error is the whole of what a
// practitioner gets, and it has to say which service and what to check.
func TestServiceGoneMessage(t *testing.T) {
	summary, detail := serviceGoneMessage("3528451425913156")

	if !strings.Contains(summary, "3528451425913156") {
		t.Errorf("summary does not name the service: %q", summary)
	}
	for _, want := range []string{"deleted", "organization", "cluster", "server_url"} {
		if !strings.Contains(detail, want) {
			t.Errorf("detail does not mention %q, so a reader is left guessing:\n%s", want, detail)
		}
	}
	// The wrong cluster is the cause people do not think of, since the id is
	// real and the token works.
	if !strings.Contains(detail, "jp.authlete.com") {
		t.Error("detail does not give the wrong-cluster case a concrete shape")
	}
}

// The bug these guard: the generated code treated any 404 as "this is gone",
// and Terraform's answer to gone is to recreate. A proxy, a maintenance page
// or a typo in server_url all return a 404, usually with HTML.
func TestA404AloneIsNotProofOfAnythingGone(t *testing.T) {
	for name, body := range map[string]string{
		"an nginx error page":   "<html><head><title>404 Not Found</title></head><body>nginx</body></html>",
		"an empty body":         "",
		"an unrelated result":   `{"resultCode":"A999999","resultMessage":"[A999999] something else"}`,
		"a json error object":   `{"error":"not_found"}`,
		"plain text":            "Not Found",
		"a different not-found": `{"error":"Client is not found"}`,
	} {
		t.Run(name, func(t *testing.T) {
			if serviceIsGone(response(http.StatusNotFound, body)) {
				t.Error("treated as a deleted service, which would recreate it and orphan the original")
			}
			if clientIsGone(response(http.StatusNotFound, body)) {
				t.Error("treated as a deleted client, which would recreate it")
			}
		})
	}
}

// What Authlete actually says when something is really gone, per endpoint.
func TestTheBodiesThatDoMeanGone(t *testing.T) {
	for name, tc := range map[string]struct {
		status  int
		body    string
		service bool
		client  bool
	}{
		"service read, server": {
			http.StatusForbidden,
			`{"resultCode":"A458203","resultMessage":"[A458203] (/service/get/) Service not found: entity is null."}`,
			true, false,
		},
		"service delete, IdP": {
			http.StatusNotFound, `{"error":"Service is not found"}`, true, false,
		},
		"client read": {
			http.StatusNotFound,
			`{"resultCode":"A001212","resultMessage":"[A001212] /client/get/{clientId}, The client (ID = 1) does not exist."}`,
			false, true,
		},
		"client delete": {
			http.StatusNotFound, `{"resultCode":"A001214","resultMessage":"[A001214] no such client"}`, false, true,
		},
	} {
		t.Run(name, func(t *testing.T) {
			if got := serviceIsGone(response(tc.status, tc.body)); got != tc.service {
				t.Errorf("serviceIsGone = %v, want %v", got, tc.service)
			}
			if got := clientIsGone(response(tc.status, tc.body)); got != tc.client {
				t.Errorf("clientIsGone = %v, want %v", got, tc.client)
			}
			// A client's path carries the service id, so either answer means
			// the client is no longer there.
			if !clientOrServiceIsGone(response(tc.status, tc.body)) {
				t.Error("clientOrServiceIsGone should accept both")
			}
		})
	}
}

// A 403 that is not A458203 is a permission problem, not a deletion. Dropping
// the resource then would plan a second service beside one that still exists.
func TestA403WithoutTheCodeIsNotGone(t *testing.T) {
	for name, body := range map[string]string{
		"insufficient rights": `{"resultCode":"A457101","resultMessage":"[A457101] access token does not have sufficient access."}`,
		"an html forbidden":   "<html>403 Forbidden</html>",
		"empty":               "",
	} {
		t.Run(name, func(t *testing.T) {
			if serviceIsGone(response(http.StatusForbidden, body)) {
				t.Error("a permission failure was read as a deletion")
			}
		})
	}
}
